/**
 * @suppress
 */
public object FfiConverterTypeVisioClient: FfiConverter<VisioClient, Pointer> {

    override fun lower(value: VisioClient): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): VisioClient {
        return VisioClient(value)
    }

    override fun read(buf: ByteBuffer): VisioClient {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: VisioClient) = 8UL

    override fun write(value: VisioClient, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



